<?php $title = 'Edycja produktu | ShopStack'; require __DIR__ . '/../layouts/header.php'; ?><p class="eyebrow">ADMIN / PRODUKTY</p><h1>Edytuj produkt</h1><form class="admin-form" method="post" enctype="multipart/form-data" action="<?= e($config['url']) ?>/admin/products/save"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($product['id']) ?>"><input name="name" value="<?= e($product['name']) ?>" required><input name="slug" value="<?= e($product['slug']) ?>" required><select name="category_id" required><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= (int) $category['id'] === (int) $product['category_id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><input name="price" type="number" step="0.01" value="<?= e($product['price']) ?>" required><input name="stock" type="number" value="<?= e($product['stock']) ?>" required><textarea name="description" required><?= e($product['description']) ?></textarea><label>Zdjęcie (JPG, PNG, WebP, maks. 2 MB)<input name="image_upload" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="button">Zapisz zmiany</button> <a href="<?= e($config['url']) ?>/admin/products">Anuluj</a></form><?php require __DIR__ . '/../layouts/footer.php'; ?>
